// Verify HMAC SHA-256 signature
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'your-32-character-secure-hmac-secret-here';
const signature = $node['Webhook Ingest'].json.headers['x-st-signature'];
const rawBody = JSON.stringify($input.item.json.body);

const calculated = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

if (signature && signature !== calculated) {
  throw new Error('HMAC signature mismatch: Unauthorized request');
}

return $input.item;
